import re

sports_kw = {
    'strong': ['nfl','nba','mlb','nhl','soccer','football','basketball','baseball','tennis','olympic','hockey','golf','cricket','rugby','playoff','quarterback','striker','yankees','red sox','espn','coach','league','championship','tournament','grand prix','formula one','f1','liverpool','real madrid','goalkeeper','midfielder','dodgers','giants','rockets','patriots','broncos','packers','rams','schumacher','manchester','arsenal','chelsea','arsenal','redskins','cowboys','knicks','lakers','bulls','heat','seahawks','steelers','bengals','astros','marlins','phillies'],
