}
business_kw = {
    'strong': ['stocks','wall street','merger','ceo','quarterly','earnings','revenue','profit','shares','investor','dividend','nasdaq','dow jones','s&p','ipo','hedge fund','mutual fund','federal reserve','inflation','recession','gdp','interest rate','bond','treasury','equity'],
    'weak': ['market','company','firm','oil','prices','dollar','economy','bank','trade','sales','financial','stock','economic','industry','sector','consumer','retail']
}
tech_kw = {
    'strong': ['nasa','mars','planet','telescope','astronaut','rocket','satellite','genome','dna','linux','windows','ipod','iphone','blackberry','microsoft','google','apple','intel','ibm','yahoo','sony','dell','oracle','sun microsystems','search engine','broadband','wi-fi','wifi','open source','firefox','spyware','spam','hacker','cyber','encryption','software','hardware','semiconductor','processor','chip','antivirus','smartphone','operating system','internet','website','online','web','mobile phone','cellphone','wireless','digital camera','mp3'],
    'weak': ['space','scientists','researchers','study','tech','technology','computer','phone','launch','discovery','species','climate','robot','virus','scientific','research','science']
}
world_kw = {
    'strong': ['president','prime minister','election','war','troops','killed','iraq','iran','afghanistan','israel','palestin','arafat','putin','bush','blair','baghdad','kabul','tehran','china','russia','north korea','south korea','rebels','militants','hostage','nuclear','peace talks','united nations','u.n.','sudan','darfur','indonesia','pakistan','india','syria','lebanon','hezbollah','hamas','al-qaeda','taliban','minister'],
    'weak': ['government','attack','protest','border','talks','peace','foreign','diplomat','embassy','treaty']
}

def score_text(text, kw_dict):
    t = ' ' + text.lower() + ' '
    score = 0
    for kw in kw_dict['strong']:
        if kw in t:
            score += 3
    for kw in kw_dict['weak']:
        # word boundary
        if re.search(r'\b' + re.escape(kw) + r'\b', t):
            score += 1
    return score

def classify(text):
    scores = {
        'Sports': score_text(text, sports_kw),
        'Science/Technology': score_text(text, tech_kw),
        'Business': score_text(text, business_kw),
        'World': score_text(text, world_kw),
    }
    max_score = max(scores.values())
    if max_score == 0:
        return 'World'
    # tie-break in priority order: Sports, Science/Technology, Business, World
    for cat in ['Sports','Science/Technology','Business','World']:
        if scores[cat] == max_score:
            return cat

results = []
for d in docs:
    text = (d.get('title','') or '') + ' ' + (d.get('description','') or '')
    cat = classify(text)
    results.append((d['article_id'], cat, d.get('title',''), d.get('description','')))

from collections import Counter
